def normalize_answer(ans):
    if not ans or not ans.strip():
        return None
    low = ans.strip().lower()
    if low in ("true", "yes"):
        return "True"
    if low in ("false", "no"):
        return "False"
    if low in ("unknown", "uncertain", "undetermined"):
        return "Unknown"
    return None

def majority_vote(answers):
    counts = Counter()
    for a in answers:
        if a is not None:
            counts[a] += 1
    if not counts:
        return None
    max_count = max(counts.values())
    for a in answers:
        if a is not None and counts[a] == max_count:
            return a
    return None

def main():
    with open(GOLD_PATH) as f:
        data = json.load(f)
    gold = {item["id"]: item["answer"] for item in data}

    files = sorted(
        glob.glob(os.path.join(TRACE_DIR, "folio_*.json")),
        key=lambda x: int(os.path.basename(x).replace("folio_", "").replace(".json", ""))
    )

    pid_answers = {}
    for fpath in files:
        with open(fpath) as f:
            d = json.load(f)
        pid = d["problem"]["id"]
        if pid not in gold:
            continue
        traces = d["sica_result"]["traces"]
        answers = [normalize_answer(t["answer"]) for t in traces]
        pid_answers[pid] = answers

    for pid, raw_answers in EXTRA_38.items():
        if pid not in gold:
            continue
        pid_answers[pid] = [normalize_answer(a) for a in raw_answers]

    sorted_pids = sorted(pid_answers.keys(), key=lambda x: int(x.split("_")[1]))
    n = len(sorted_pids)
    print(f"Total questions: {n}")
    assert n == 204, f"Expected 204, got {n}"

    K = 12
    for pid in sorted_pids:
        assert len(pid_answers[pid]) == K, f"{pid} has {len(pid_answers[pid])} traces, expected {K}"

    # SC@12
    sc_correct = 0
    for pid in sorted_pids:
        mv = majority_vote(pid_answers[pid])
        if mv == gold[pid]:
            sc_correct += 1
    sc_acc = sc_correct / n
    print(f"SC@12: {sc_correct}/{n} = {sc_acc*100:.2f}%")

    # Oracle@12
    oracle_correct = 0
    for pid in sorted_pids:
        if any(a == gold[pid] for a in pid_answers[pid]):
            oracle_correct += 1
    oracle_acc = oracle_correct / n
    print(f"Oracle@12: {oracle_correct}/{n} = {oracle_acc*100:.2f}%")

    oracle_gap = (oracle_acc - sc_acc) * 100
    print(f"Oracle Gap: {oracle_gap:.2f}pp")

    # Oracle curve: K=1,2,3,4,6,8,12
    random.seed(42)
    np.random.seed(42)
    k_values = [1, 2, 3, 4, 6, 8, 12]
    n_samples = 100
    oracle_curve = {}

    for k in k_values:
        trial_accs = []
        for _ in range(n_samples):
            correct = 0
            for pid in sorted_pids:
                answers = pid_answers[pid]
                subset = random.sample(answers, k)
                if any(a == gold[pid] for a in subset):
                    correct += 1
            trial_accs.append(correct / n)
        mean_acc = float(np.mean(trial_accs))
        std_acc = float(np.std(trial_accs))
        oracle_curve[str(k)] = {"mean": round(mean_acc, 6), "std": round(std_acc, 6)}
        print(f"  Oracle@{k}: {mean_acc*100:.2f}% ± {std_acc*100:.2f}%")

